CREATE TABLE credit_accounts(workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id),balance INTEGER NOT NULL DEFAULT 0 CHECK(balance>=0),reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=balance),updated_at TEXT NOT NULL);
CREATE TABLE credit_ledger(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES users(id),job_id TEXT,item_id TEXT,event_key TEXT NOT NULL UNIQUE,kind TEXT NOT NULL CHECK(kind IN('grant','reserve','settle','release','adjustment')),amount INTEGER NOT NULL,balance_after INTEGER NOT NULL,reserved_after INTEGER NOT NULL,description TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX ledger_workspace_time ON credit_ledger(workspace_id,created_at DESC,id);
CREATE TABLE provider_settings(workspace_id TEXT NOT NULL REFERENCES workspaces(id),provider_id TEXT NOT NULL,encrypted_secret TEXT,key_hint TEXT,enabled INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL,PRIMARY KEY(workspace_id,provider_id));
CREATE TABLE quotes(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES users(id),input_hash TEXT NOT NULL,input_json TEXT NOT NULL,pricing_version TEXT NOT NULL,max_credits INTEGER NOT NULL CHECK(max_credits>=0),units INTEGER NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE jobs(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES users(id),project_id TEXT REFERENCES projects(id),api_key_id TEXT REFERENCES api_keys(id),operation TEXT NOT NULL,provider_id TEXT NOT NULL,prompt TEXT NOT NULL,input_json TEXT NOT NULL,input_hash TEXT NOT NULL,request_id TEXT NOT NULL,pricing_version TEXT NOT NULL,status TEXT NOT NULL,stage TEXT NOT NULL,requested_credits INTEGER NOT NULL,settled_credits INTEGER NOT NULL DEFAULT 0,error_message TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(workspace_id,user_id,request_id));
CREATE INDEX jobs_workspace_time ON jobs(workspace_id,created_at DESC,id);
CREATE TABLE job_items(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES jobs(id),workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES users(id),item_index INTEGER NOT NULL,input_json TEXT NOT NULL,status TEXT NOT NULL,phase TEXT NOT NULL DEFAULT 'queued',credits INTEGER NOT NULL CHECK(credits>=0),asset_id TEXT REFERENCES assets(id),remote_id TEXT,remote_json TEXT,result_json TEXT,result_text TEXT,error_message TEXT,lease_owner TEXT,lease_until TEXT,fence INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TEXT NOT NULL,cancel_requested INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(job_id,item_index));
CREATE INDEX job_items_claim ON job_items(status,next_attempt_at,lease_until);
CREATE TABLE job_events(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id TEXT NOT NULL REFERENCES workspaces(id),job_id TEXT NOT NULL REFERENCES jobs(id),type TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX events_workspace_cursor ON job_events(workspace_id,id);
CREATE TABLE pending_applies(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),document_id TEXT NOT NULL REFERENCES documents(id),job_id TEXT NOT NULL REFERENCES jobs(id),item_id TEXT NOT NULL UNIQUE REFERENCES job_items(id),asset_id TEXT NOT NULL REFERENCES assets(id),base_revision INTEGER NOT NULL,target_layer_id TEXT,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE messages(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),project_id TEXT NOT NULL REFERENCES projects(id),user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL,content TEXT NOT NULL,job_id TEXT REFERENCES jobs(id),metadata_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
CREATE INDEX messages_project_time ON messages(project_id,created_at,id);
CREATE TABLE inspiration_favorites(user_id TEXT NOT NULL REFERENCES users(id),inspiration_id TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(user_id,inspiration_id));
CREATE TABLE redemption_codes(id TEXT PRIMARY KEY,code_hash TEXT NOT NULL UNIQUE,credits INTEGER NOT NULL CHECK(credits>0),expires_at TEXT,redeemed_by TEXT REFERENCES users(id),workspace_id TEXT REFERENCES workspaces(id),redeemed_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE workspace_billing(workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id),credit_mode TEXT NOT NULL DEFAULT 'shared' CHECK(credit_mode IN('shared','allocated')),concurrency_limit INTEGER NOT NULL DEFAULT 2 CHECK(concurrency_limit BETWEEN 1 AND 10));
CREATE TABLE member_budgets(workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES users(id),credit_limit INTEGER CHECK(credit_limit>=0),spent INTEGER NOT NULL DEFAULT 0 CHECK(spent>=0),reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0),PRIMARY KEY(workspace_id,user_id));
CREATE TABLE billing_events(id TEXT PRIMARY KEY,provider_id TEXT NOT NULL,event_id TEXT NOT NULL,order_id TEXT NOT NULL,event_json TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(provider_id,event_id));
